class Solution {
    public: int minSubarray(vector<int>& nums,int p){
        long long total=accumulate(nums.begin(),nums.end(),0LL);
        int remainder=total%p;
        if(!remainder)return 0;
        unordered_map<int,int> latest{
            {
                0,-1
            }
        };
        int prefix=0,answer=nums.size();
        for(int i=0;i<(int)nums.size();++i){
            prefix=(prefix+(long long)nums[i])%p;
            int needed=(prefix-remainder+p)%p;
            if(latest.count(needed))answer=min(answer,i-latest[needed]);
            latest[prefix]=i;
        }
        return answer==(int)nums.size()?-1:answer;
    }
};
